contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to forward to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");

        // observe owner and c balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe owner and c balance after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        // If the call did not revert, then owner must be unchanged and c must not hold more funds than before.
        // Formally: reverted OR (owner unchanged AND balanceAfter <= balanceBefore)
        assert(reverted || (ownerAfter == ownerBefore && balanceAfter <= balanceBefore));
    }

    receive() external payable {}
}

